function enCategories(){return '<div class="nv-site" data-nv-page="categories"><nav class="nv-crumb"><a href="#home">Home</a> / All categories</nav><div class="nv-title-row"><div><small>THE MARKETPLACE</small><h1>Explore every space and service.</h1><p>Six existing market categories; choose one for its verified specialties.</p></div></div><div class="nv-grid">'+C.map(c=>'<a class="nv-card" href="#section?category='+c[0]+'"><div class="nv-card-cover">'+img(photo(c[3]),c[2])+'</div><div class="nv-card-body"><h3>'+c[2]+'</h3><b>Browse category ↗</b></div></a>').join('')+'</div></div>'}
function enSection(){const category=new URLSearchParams(window.marketLocation.hash.split('?')[1]||'').get('category')||'furniture',c=C.find(x=>x[0]===category)||C[0],seen=new Set();const specs=taxonomy.filter(g=>groups[category]?.includes(g.key)).flatMap(g=>(g.specialties||[]).map(s=>({name:s.name_en||s.name_ar,key:s.key,group:g.name_en||g.name_ar}))).filter(s=>!seen.has(s.key)&&seen.add(s.key));return '<div class="wrap br-section-page" data-nv-page="section"><nav class="br-crumb"><a href="#home">Home</a> › <a href="#categories">All categories</a> › '+esc(c[2])+'</nav><section class="br-section-hero"><div class="br-section-hero-copy"><small>BIET AL REEF / CATEGORY</small><h1>'+c[2]+'</h1><p>Discover relevant products, providers and specialties.</p><div class="br-hero-cta"><a href="#results?category='+c[0]+'">Browse listings ↗</a><a href="#studio">Design studio</a></div></div>'+img(photo(c[3]),c[2])+'</section><section class="br-section-content"><div class="br-section-heading"><div><span>MARKET TAXONOMY</span><h2>Browse specialties</h2><p>Based on the existing business classification system.</p></div><span class="br-section-count">'+(taxonomy.length?specs.length+' specialties':'Loading specialties…')+'</span></div><div class="br-section-grid">'+(taxonomy.length?specs.map(s=>'<a class="br-section-specialty" href="#results?category='+c[0]+'&specialty='+encodeURIComponent(s.key)+'"><div class="br-specialty-symbol">◈</div><div><small>'+esc(s.group)+'</small><strong>'+esc(s.name)+'</strong><span>Browse listings ↗</span></div></a>').join(''):'<p>Loading approved specialties…</p>')+'</div></section></div>'}
function enInfo(){let slug=new URLSearchParams(window.marketLocation.hash.split('?')[1]||'').get('slug')||'about',d=infoDocuments[slug];if(!d)return '';return '<div class="wrap footer-document" data-nv-page="info"><nav class="nv-crumb"><a href="#home">Home</a> / Guides</nav><section class="footer-page-hero"><span class="footer-eyebrow">BIET AL REEF GUIDE</span><h1>'+esc(d.enTitle)+'</h1><p>'+esc(d.enIntro)+'</p></section><section class="footer-page-body"><h2>What you need to know</h2><div class="footer-facts">'+(d.enItems||[]).map((s,i)=>'<article class="footer-fact"><span>'+String(i+1).padStart(2,'0')+'</span><p>'+esc(s)+'</p></article>').join('')+'</div><aside class="footer-help"><span>Need help?</span><a href="#info?slug=customer-service" class="button primary">Customer support ↗</a></aside></section></div>'}
