Object.assign(translations,{'ابحث عن منتج أو خدمة أو متجر':'Search products, services or stores','ابحث عن قطعة':'Search items','التخصصات الفرعية غير متاحة مؤقتًا':'Specialties are temporarily unavailable','سوق بيت الريف الرئيسية':'Biet Al Reef Marketplace home','افتح سلة المشتريات':'Open shopping cart','فتح القائمة':'Open menu','انتقل إلى المحتوى':'Skip to content'});
const nvOriginalText=new WeakMap(),nvOriginalAttr=new WeakMap();
function translate(root){
 if(!root)return;
 const translateText=s=>{
   const key=s?.trim();if(!key)return null;
   const match=taxonomy.flatMap(g=>[g,...(g.specialties||[])]).find(x=>x.name_ar===key);
   const exact=translations[key]||match?.name_en;if(exact)return exact;
   let output=key;
   for(const [ar,enText] of Object.entries(translations).sort((a,b)=>b[0].length-a[0].length)){
     if(ar.length>=3&&output.includes(ar))output=output.split(ar).join(enText);
   }
   output=output.split(' سم').join(' cm');
   return output!==key?output:null;
 };
 const nodes=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),list=[];
 while(nodes.nextNode()){const node=nodes.currentNode;if(!node.parentElement?.closest('script,style,svg,pre,code,.nv-site'))list.push(node)}
 for(const node of list){
   if(!nvOriginalText.has(node))nvOriginalText.set(node,node.nodeValue);
   const original=nvOriginalText.get(node),translated=en()?translateText(original):null;
   node.nodeValue=translated?(original.replace(original.trim(),translated)):original;
 }
 for(const el of root.querySelectorAll('[placeholder],[aria-label]')){
   let attrs=nvOriginalAttr.get(el);
   if(!attrs){attrs={};nvOriginalAttr.set(el,attrs)}
   for(const name of ['placeholder','aria-label']){
     if(!el.hasAttribute(name))continue;
     if(!Object.hasOwn(attrs,name))attrs[name]=el.getAttribute(name);
     const translated=en()?translateText(attrs[name]):null;
     el.setAttribute(name,translated||attrs[name]);
   }
 }
}

function nvFooter(){
 const foot=document.querySelector('#footer-guide');if(!foot||foot.dataset.nvLanguage===lang)return;
 const groups=footerSections.map(s=>({title:s.title,links:s.links})).concat([
 {title:'التصنيفات',links:C.map(c=>[c[1],'#results?category='+c[0]])},
 {title:'المدن والمناطق',links:[['العين','#results'],['أبوظبي','#results'],['دبي','#results'],['الشارقة','#results'],['عجمان','#results'],['رأس الخيمة','#results'],['الفجيرة','#results'],['أم القيوين','#results']]}
 ]);
 const l=s=>en()?(translations[s]||s):s;
 foot.innerHTML='<div class="footer-guide-top"><span>'+tr('كل ما تحتاجه عن السوق','Everything about the marketplace')+'</span><button type="button" data-footer-top>'+tr('العودة للأعلى ↑','Back to top ↑')+'</button></div><div class="footer-guide-grid">'+groups.map((g,i)=>'<section class="footer-guide-group market-ux-footer-section"><h2>'+esc(l(g.title))+'</h2><div class="footer-guide-links">'+g.links.map(([label,href])=>'<a href="'+esc(href)+'"'+(i===6?' data-drawer-city="'+esc(label)+'"':'')+'>'+esc(l(label))+' <span aria-hidden="true">↗</span></a>').join('')+'</div></section>').join('')+'</div><nav class="footer-legal" aria-label="'+tr('السياسات والروابط المهمة','Policies and important links')+'">'+[['الخصوصية','Privacy','#policy?slug=privacy'],['شروط الاستخدام','Terms of use','#policy?slug=legal'],['ملفات الارتباط','Cookies','#policy?slug=cookies'],['حماية البيانات','Data protection','#info?slug=data-protection'],['خريطة الموقع','Sitemap','#sitemap']].map(([a,b,href])=>'<a href="'+href+'">'+tr(a,b)+'</a>').join('')+'</nav>';
 foot.dataset.nvLanguage=lang;
}

